 public class Program {
  [STAThread] public static int Main(string[] args){
   try {
    if(args.Length>0&&args[0]=="--self-test")return SelfTest.Run(args.Length>1?args[1]:Path.Combine(Path.GetTempPath(),"JingDllTests"));
    if(args.Length==3&&args[0]=="--verify-package"){Engine.ValidateMicrosoftPackage(args[1]);File.WriteAllText(args[2],"PASS: Authenticode trust and Microsoft Corporation publisher\r\nSHA256: "+Engine.Hash(args[1]));return 0;}
    if(args.Length>0&&args[0]=="--maintenance")return Maintenance(args);
    var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show(e.Exception.Message,"景修 DLL",MessageBoxButton.OK,MessageBoxImage.Error);e.Handled=true;};
    if(args.Length==2&&args[0]=="--ui-test"){Engine.Home=Path.Combine(Path.GetFullPath(args[1]),"ui-data");Directory.CreateDirectory(Engine.Home);}
    var ui=new MainView();if(args.Length==2&&args[0]=="--ui-test"){ui.Window.Loaded+=async(s,e)=>{try{await ui.UiSmoke(args[1]);}catch(Exception ex){File.WriteAllText(Path.Combine(args[1],"ui-error.txt"),ex.ToString());Environment.ExitCode=1;}finally{ui.Window.Close();}};}
    if(args.Length>1&&args[0]=="--preview"){string shot=args[1];string shotPage=args.Length>2?args[2]:"Home";ui.Window.Loaded+=(s,e)=>{ui.Window.Dispatcher.BeginInvoke(new Action(()=>{ui.Navigate(shotPage);}),System.Windows.Threading.DispatcherPriority.ApplicationIdle);var settle=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(900)};settle.Tick+=(s2,e2)=>{settle.Stop();ui.Window.Dispatcher.Invoke(new Action(()=>{ui.Window.UpdateLayout();var bmp=new RenderTargetBitmap((int)ui.Window.ActualWidth,(int)ui.Window.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(ui.Window);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create(shot))enc.Save(f);ui.Window.Close();}),System.Windows.Threading.DispatcherPriority.ContextIdle);};settle.Start();};}int appExit=app.Run(ui.Window);return Environment.ExitCode==0?appExit:Environment.ExitCode;
   }catch(Exception ex){File.WriteAllText(Path.Combine(Path.GetTempPath(),"JingDll-startup-error.txt"),ex.ToString());if(args.Length==0)MessageBox.Show(ex.Message,"启动失败");return 1;}
  }
  static int Maintenance(string[] args){if(args.Length!=3||!new[]{"scan","verify","repair"}.Contains(args[1])||args[2].Length!=32||!args[2].All(Uri.IsHexDigit))return 2;
   if(!new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator))return 5;
   Directory.CreateDirectory(Engine.Home);string log=Path.Combine(Engine.Home,"maintenance-"+args[2]+".log");int result=0;try {
    var commands=args[1]=="repair"?new[]{new[]{"dism.exe","/Online /Cleanup-Image /RestoreHealth"},new[]{"sfc.exe","/scannow"}}:args[1]=="scan"?new[]{new[]{"dism.exe","/Online /Cleanup-Image /ScanHealth"}}:new[]{new[]{"sfc.exe","/verifyonly"}};
    var app=new Application();var output=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(20),FontFamily=new FontFamily("Consolas,Microsoft YaHei UI"),FontSize=13};var w=new Window{Title="景修 DLL · Windows 系统任务（执行期间请勿关机）",Width=900,Height=600,Content=output};bool done=false;w.Closing+=(s,e)=>{if(!done){e.Cancel=true;MessageBox.Show("系统任务仍在运行，请等待完成。", "任务进行中");}};
    w.Loaded+=async(s,e)=>{try{await Task.Run(()=>{foreach(var cmd in commands){Action<string> append=line=>{if(line==null)return;lock(output){File.AppendAllText(log,line+Environment.NewLine,Encoding.UTF8);}w.Dispatcher.BeginInvoke(new Action(()=>{output.AppendText(line+Environment.NewLine);output.ScrollToEnd();}));};append("> "+cmd[0]+" "+cmd[1]);var info=new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,cmd[0]),cmd[1]){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};if(cmd[0]=="sfc.exe"){info.StandardOutputEncoding=Encoding.Unicode;info.StandardErrorEncoding=Encoding.Unicode;}using(var p=new Process{StartInfo=info}){p.OutputDataReceived+=(a,b)=>append(b.Data);p.ErrorDataReceived+=(a,b)=>append(b.Data);p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();p.WaitForExit();result=p.ExitCode;append("退出码："+result);if(result!=0&&result!=3010)break;}}});output.AppendText("\r\n任务已结束，请阅读上方工具结论。退出码并不代表全部 DLL 故障均已修复。");}catch(Exception ex){result=1;output.AppendText(ex.ToString());File.AppendAllText(log,ex.ToString());}finally{done=true;File.WriteAllText(log+".exit",result.ToString());w.Title="景修 DLL · 系统任务已结束（可关闭）";}};app.Run(w);
   }catch(Exception ex){File.AppendAllText(log,ex.ToString());return 1;}return result;
  }
 }
