   Click("installX64",()=>InstallRuntime("x64"));Click("installX86",()=>InstallRuntime("x86"));Click("vcDocs",()=>Open("https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist"));Click("directxDocs",()=>Open("https://www.microsoft.com/en-us/download/details.aspx?id=35"));Click("netDocs",()=>Open("https://dotnet.microsoft.com/en-us/download/dotnet"));Click("refreshRuntime",RuntimeInfo);
