   searchTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(220)};searchTimer.Tick+=(s,e)=>{searchTimer.Stop();Filter();};Get<TextBox>("catalogSearch").TextChanged+=(s,e)=>{searchTimer.Stop();searchTimer.Start();};Get<ComboBox>("archFilter").SelectionChanged+=(s,e)=>Filter();
   Get<DataGrid>("scanGrid").SelectionChanged+=(s,e)=>{var f=Get<DataGrid>("scanGrid").SelectedItem as Finding;if(f!=null)Get<TextBox>("scanDetail").Text=f.Dll+" · "+f.Status+"\r\n候选路径："+f.Location+"\r\n"+f.Detail+"\r\n"+Advice(f.Dll);};
