  public void Navigate(string page){foreach(string name in new[]{"Home","Scan","Database","Runtime","Tools","Backups","Logs","About"}){Get<FrameworkElement>("page"+name).Visibility=page==name?Visibility.Visible:Visibility.Collapsed;var b=Get<Button>("nav"+name);b.Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(page==name?"#25447A":"#101D36"));b.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(page==name?"#FFFFFF":"#AEBBD3"));}if(page=="Logs")Logs();if(page=="Backups")RefreshBackups();if(page=="Runtime")RuntimeInfo();}
