  void ChooseApp(bool run){if(busy)return;var f=Pick("选择发生报错的程序","Windows 程序与动态库|*.exe;*.dll");if(f==null)return;selectedApp=f;Get<TextBox>("appPath").Text=f;findings.Clear();Get<DataGrid>("scanGrid").ItemsSource=null;Get<TextBox>("scanDetail").Text="已选择程序，请开始诊断。";Navigate("Scan");if(run)Scan();}
  async void Scan(){if(busy)return;if(selectedApp==null){ChooseApp(false);if(selectedApp==null)return;}Busy(true,"正在解析 PE 依赖…");try{string file=selectedApp;findings=await Task.Run(()=>Engine.Scan(file,n=>Window.Dispatcher.BeginInvoke(new Action(()=>Status("检查依赖："+n)))));Get<DataGrid>("scanGrid").ItemsSource=findings;Set("statIssues",findings.Count(x=>x.Problem).ToString());Get<TextBox>("scanDetail").Text="扫描完成："+findings.Count+" 个直接导入模块，"+findings.Count(x=>x.Problem)+" 个静态疑点。选择结果查看详情。\r\n未发现静态疑点不代表程序运行一定正常；动态加载、托管绑定、SxS 和权限问题需要进一步确认。";Status("诊断完成 · "+findings.Count+" 个模块");}catch(Exception ex){Error(ex);}finally{Busy(false,"诊断任务结束 · 详见结果与操作日志");}}
  static string Advice(string name){name=name.ToLowerInvariant();if(name.StartsWith("msvc")||name.StartsWith("vcruntime"))return "建议安装对应架构和版本的官方 Visual C++ 运行库。";if(name.StartsWith("d3dx")||name.StartsWith("xinput1_3")||name.StartsWith("xaudio2_7"))return "建议使用微软 DirectX 旧版组件安装程序。";return "系统组件请使用 DISM / SFC；第三方 DLL 请从原软件安装包恢复，避免跨版本替换。";}
  void Filter(){if(catalog==null)return;string term=Get<TextBox>("catalogSearch").Text.Trim();var combo=Get<ComboBox>("archFilter").SelectedItem as ComboBoxItem;string arch=combo==null?"全部架构":combo.Content.ToString();filtered=catalog.Where(x=>(arch=="全部架构"||x.Architecture==arch)&&(term.Length==0||(x.Name+" "+x.Description+" "+x.Version+" "+x.Category).IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0)).ToList();Get<DataGrid>("catalogGrid").ItemsSource=filtered.Take(500).ToList();Set("catalogCount","匹配 "+filtered.Count.ToString("N0")+" 条 · 显示前 500 条，可缩小搜索或导出全部匹配结果");}
  void ExportCatalog(){SaveText("DLL数据库检索.tsv","TSV 数据|*.tsv","Name\tArchitecture\tVersion\tCategory\tDescription\tSource\r\n"+String.Join("\r\n",filtered.Select(x=>String.Join("\t",new[]{x.Name,x.Architecture,x.Version,x.Category,x.Description,x.Source}))));}
  string Csv(string s){s=s??"";if(s.Length>0&&"=+-@".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
  void ExportReport(){if(findings.Count==0)throw new InvalidOperationException("请先完成一次有依赖结果的诊断。");SaveText("DLL诊断报告.csv","CSV 报告|*.csv","程序,"+Csv(selectedApp)+"\r\n生成时间,"+Csv(DateTime.Now.ToString("s"))+"\r\n说明,静态直接依赖检查；候选路径不代表加载器实际选择\r\nDLL,状态,架构,版本,候选路径,说明\r\n"+String.Join("\r\n",findings.Select(f=>String.Join(",",new[]{f.Dll,f.Status,f.Arch,f.Version,f.Location,f.Detail}.Select(Csv)))));}
