  async void Inspect(){if(busy)return;string p=Pick("检查文件信息","Windows PE 文件|*.dll;*.exe");if(p==null)return;Busy(true,"正在读取文件、计算哈希并校验签名…");try{string report=await Task.Run(()=>Engine.Inspect(p));var box=new TextBox{Text=report,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(20)};var panel=new DockPanel();var button=new Button{Content="导出文件信息",Margin=new Thickness(20),HorizontalAlignment=HorizontalAlignment.Right};DockPanel.SetDock(button,Dock.Bottom);panel.Children.Add(button);panel.Children.Add(box);button.Click+=(s,e)=>Safe(()=>SaveText("文件检查.txt","文本|*.txt",report));new Window{Owner=Window,Title="PE 文件详情",Width=820,Height=600,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=panel}.ShowDialog();Engine.Log("文件检查："+p);}catch(Exception ex){Error(ex);}finally{Busy(false,"文件检查任务结束");}}
  async void Repair(){if(busy)return;try{if(selectedApp==null)throw new InvalidOperationException("请先选择并诊断目标应用。");var selected=Get<DataGrid>("scanGrid").SelectedItem as Finding;if(selected==null)throw new InvalidOperationException("请选择需要修复的 DLL 结果。");if(selected.Dll.StartsWith("api-ms-",StringComparison.OrdinalIgnoreCase)||selected.Dll.StartsWith("ext-ms-",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("API Set 是系统映射合约，请使用 Windows 修复。");string source=Pick("选择原软件安装包中可信且同名的 DLL","动态链接库|*.dll");if(source==null)return;if(!String.Equals(Path.GetFileName(source),selected.Dll,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("必须选择名称为 "+selected.Dll+" 的文件。");Busy(true,"校验修复来源…");string sig=await Task.Run(()=>Engine.Signature(source));string hash=Engine.Hash(source);string target=Path.Combine(Path.GetDirectoryName(selectedApp),selected.Dll);if(MessageBox.Show(Window,"来源："+source+"\r\n目标："+target+"\r\n签名："+sig+"\r\nSHA-256："+hash+"\r\n\r\n请关闭目标程序并确认文件来自原软件的可信安装包。将检查架构和所需导出函数，备份原文件后替换。确定继续？","确认应用 DLL 修复",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;await Task.Run(()=>Engine.Replace(selectedApp,source));RefreshBackups();MessageBox.Show(Window,"修复文件已部署并记录备份。请重新启动目标程序验证运行结果。","部署完成");}catch(Exception ex){Error(ex);}finally{Busy(false,"应用修复任务结束");}}
  void RefreshBackups(){var records=Engine.Records();Get<DataGrid>("backupGrid").ItemsSource=records.OrderByDescending(x=>x.Time).ToList();Set("statBackups",records.Count(x=>!x.RolledBack&&x.Status=="已部署").ToString());}
  void Rollback(){var rec=Get<DataGrid>("backupGrid").SelectedItem as RepairRecord;if(rec==null)throw new InvalidOperationException("请选择一条修复记录。");if(MessageBox.Show(Window,"关闭目标程序后回滚：\r\n"+rec.Target+"\r\n原来不存在的文件将被移除。继续？","确认回滚",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;Engine.Rollback(rec);RefreshBackups();Status("回滚完成");}
