  void RuntimeInfo(){var sb=new StringBuilder();sb.AppendLine("操作系统："+Environment.OSVersion+" / "+(Environment.Is64BitOperatingSystem?"64-bit":"32-bit"));foreach(var view in new[]{RegistryView.Registry32,RegistryView.Registry64}){if(view==RegistryView.Registry64&&!Environment.Is64BitOperatingSystem)continue;using(var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,view))using(var key=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){if(key!=null)foreach(string id in key.GetSubKeyNames()){using(var k=key.OpenSubKey(id)){string name=Convert.ToString(k.GetValue("DisplayName"));if(name.IndexOf("Visual C++",StringComparison.OrdinalIgnoreCase)>=0)sb.AppendLine(name+"  ["+view+"]");}}}}string net=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","shared","Microsoft.WindowsDesktop.App");if(Directory.Exists(net))foreach(var dir in Directory.GetDirectories(net))sb.AppendLine(".NET Desktop Runtime "+Path.GetFileName(dir));sb.AppendLine("提示：以上为安装记录，不等同于完整性验证。");Get<TextBox>("runtimeInfo").Text=sb.ToString();}
