   Navigate("Database");Get<TextBox>("catalogSearch").Text="msvcp140";await Task.Delay(300);if(filtered.Count==0||filtered.Any(x=>(x.Name+" "+x.Description+" "+x.Version+" "+x.Category).IndexOf("msvcp140",StringComparison.OrdinalIgnoreCase)<0))throw new Exception("Search failed");notes.Add("PASS: database search");Get<ComboBox>("archFilter").SelectedIndex=2;if(filtered.Any(x=>x.Architecture!="x86"))throw new Exception("Architecture filter failed");notes.Add("PASS: database architecture filter");
