  }
  async void InstallRuntime(string arch){if(busy)return;if(arch=="x64"&&!Environment.Is64BitOperatingSystem){Error(new InvalidOperationException("32 位系统不能安装 x64 运行库。"));return;}if(MessageBox.Show(Window,"从微软官方下载 Visual C++ v14 "+arch+" 安装包，校验有效签名与微软发布者后启动安装。安装器可能请求管理员授权。继续？","官方运行库安装",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;Busy(true,"连接微软官方下载服务…");try{Directory.CreateDirectory(Path.Combine(Engine.Home,"Downloads"));string path=Path.Combine(Engine.Home,"Downloads","vc_redist."+arch+"-"+Guid.NewGuid().ToString("N")+".exe");ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new WebClient()){client.DownloadProgressChanged+=(s,e)=>Status("下载 Visual C++ "+arch+"："+e.ProgressPercentage+"%");await client.DownloadFileTaskAsync(new Uri("https://aka.ms/vs/17/release/vc_redist."+arch+".exe"),path);}Status("校验安装包签名与发布者…");await Task.Run(()=>{Engine.ValidateMicrosoftPackage(path);});Engine.Log("官方运行库包："+arch+" SHA256="+Engine.Hash(path));using(var p=Process.Start(new ProcessStartInfo(path,"/install /passive /norestart"){UseShellExecute=true,Verb="runas"})){await Task.Run(()=>p.WaitForExit());int code=p.ExitCode;Engine.Log("运行库安装退出码："+code);MessageBox.Show(Window,code==0?"运行库安装已完成。":code==3010?"运行库安装已完成，需要重新启动 Windows。":code==1638?"系统已有该产品的其他版本。请查看已安装应用或使用官方安装器的修复选项。":"安装器退出码："+code+"。请根据官方安装器结果排查。","安装结果");}RuntimeInfo();}catch(Exception ex){Error(ex);}finally{Busy(false,"运行库安装任务结束");}}
  async void SystemTask(string task){if(busy)return;string command=task=="repair"?"DISM.exe /Online /Cleanup-Image /RestoreHealth\r\nsfc.exe /scannow":task=="scan"?"DISM.exe /Online /Cleanup-Image /ScanHealth":"sfc.exe /verifyonly";if(MessageBox.Show(Window,"将以管理员权限执行：\r\n\r\n"+command+"\r\n\r\n任务会打开独立进度窗口并保存日志。修复可能需要联网，耗时较长，请勿中途关机。继续？","Windows 系统任务",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;Busy(true,"Windows 系统任务执行中 · 请查看独立进度窗口");try{string token=Guid.NewGuid().ToString("N");using(var p=Process.Start(new ProcessStartInfo(typeof(Program).Assembly.Location,"--maintenance "+task+" "+token){UseShellExecute=true,Verb="runas"})){await Task.Run(()=>p.WaitForExit());Engine.Log("Windows 系统任务 "+task+"；退出码 "+p.ExitCode);string log=Path.Combine(Engine.Home,"maintenance-"+token+".log");MessageBox.Show(Window,"任务窗口已关闭，退出码："+p.ExitCode+"\r\n请依据工具输出确认检查与修复结果。\r\n日志："+log,"系统任务结束");}}catch(Exception ex){Error(ex);}finally{Busy(false,"系统任务结束 · 日志可在 Windows 修复页查看");}}
 }
